"use client";

import { useTheme } from "next-themes";
import { useEffect } from "react";

const THEME_COLORS = {
  pinktra: "#f0b4d7",
  light: "#ffffff",
  dark: "#09090b",
};

export default function ThemeMeta() {
  const { theme } = useTheme();

  useEffect(() => {
    const meta = document.querySelector<HTMLMetaElement>('meta[name="theme-color"]');

    if (!meta) return;

    meta.content = THEME_COLORS[theme as keyof typeof THEME_COLORS] ?? THEME_COLORS.pinktra;
  }, [theme]);

  return null;
}

export const themeMetaInitScript = `(()=>{let e={pinktra:"#f0b4d7",light:"#ffffff",dark:"#09090b"},t=localStorage.getItem("theme");t&&"system"!==t||(t=window.matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light");let r=document.querySelector('meta[name="theme-color"]');r&&r.setAttribute("content",e[t]??e.pinktra)})();`;

